    const supabase = supabaseForUser(ctx);
    const like = `%${query}%`;
    const { data, error } = await supabase.from("places").select("id, name, category, arrondissement, neighborhood_name, rating").or(`name.ilike.${like},neighborhood_name.ilike.${like}`).limit(limit ?? 20);
